"use strict";
// Tipos primitivos
/*
string
number
boolean
any
*/
// String pra texto.
let username;
username = "Israel";
// Number para números
let total;
total = 4;
// Recebe números quebrados. No Brasil usamos vírgula, mas na programação usamos ponto.
total = 4.1;
// Boolean para verdadeiro ou falso
// Tipagem explicita
let isLoading;
isLoading = true;
isLoading = false;
// Tipagem explicita define claramente o tipo da variavel
// enquanto a inferência de tipos permite que o TypeScript deduza o tipo com base no valor atribuído.
// inferencia de tipos
// tipagem implicita
let showMessage = "Olá, tudo bem?";
let num = 12;
console.log(showMessage);


